CREATE TYPE "StockMovementType" AS ENUM ('OPENING_STOCK','PURCHASE','PURCHASE_RETURN','SALE','SALE_RETURN','ADJUSTMENT_IN','ADJUSTMENT_OUT','DAMAGE','TRANSFER_IN','TRANSFER_OUT');
CREATE TYPE "StockAdjustmentReason" AS ENUM ('OPENING_BALANCE','PHYSICAL_COUNT','DAMAGE_CORRECTION','LOST','FOUND','DATA_CORRECTION','OTHER');
CREATE TYPE "SerialStatus" AS ENUM ('IN_STOCK','RESERVED','SOLD','RETURNED','DAMAGED','IN_RMA','SENT_TO_SUPPLIER','RECEIVED_FROM_SUPPLIER','DELIVERED_TO_CUSTOMER','SCRAPPED');

CREATE TABLE "Warehouse" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"description" TEXT,"address" TEXT,"isDefault" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Warehouse_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StockMovement" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"productId" TEXT NOT NULL,"type" "StockMovementType" NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"referenceType" TEXT,"referenceId" TEXT,"unitCost" DECIMAL(18,2),"note" TEXT,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockMovement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StockBalance" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"productId" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "StockBalance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StockAdjustment" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"reason" "StockAdjustmentReason" NOT NULL,"note" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "StockAdjustment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StockAdjustmentLine" ("id" TEXT NOT NULL,"adjustmentId" TEXT NOT NULL,"productId" TEXT NOT NULL,"direction" "StockMovementType" NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unitCost" DECIMAL(18,2),CONSTRAINT "StockAdjustmentLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SerialItem" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"warehouseId" TEXT NOT NULL,"productId" TEXT NOT NULL,"serialNumber" TEXT NOT NULL,"status" "SerialStatus" NOT NULL DEFAULT 'IN_STOCK',"purchaseId" TEXT,"saleId" TEXT,"customerId" TEXT,"supplierId" TEXT,"warrantyStart" TIMESTAMP(3),"warrantyEnd" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SerialItem_pkey" PRIMARY KEY ("id"));

