CREATE UNIQUE INDEX "StockBalance_businessId_warehouseId_productId_key" ON "StockBalance"("businessId","warehouseId","productId"); CREATE INDEX "StockBalance_businessId_productId_idx" ON "StockBalance"("businessId","productId"); CREATE INDEX "StockBalance_businessId_warehouseId_idx" ON "StockBalance"("businessId","warehouseId");
CREATE INDEX "StockAdjustment_businessId_createdAt_idx" ON "StockAdjustment"("businessId","createdAt"); CREATE INDEX "StockAdjustment_businessId_warehouseId_idx" ON "StockAdjustment"("businessId","warehouseId"); CREATE INDEX "StockAdjustmentLine_adjustmentId_idx" ON "StockAdjustmentLine"("adjustmentId"); CREATE INDEX "StockAdjustmentLine_productId_idx" ON "StockAdjustmentLine"("productId");
CREATE UNIQUE INDEX "SerialItem_businessId_serialNumber_key" ON "SerialItem"("businessId","serialNumber"); CREATE INDEX "SerialItem_businessId_productId_idx" ON "SerialItem"("businessId","productId"); CREATE INDEX "SerialItem_businessId_warehouseId_idx" ON "SerialItem"("businessId","warehouseId"); CREATE INDEX "SerialItem_businessId_status_idx" ON "SerialItem"("businessId","status");

